subroutine SumVector(data[] as integer by reference, index as integer, size as integer) as integer
    if index >= size then
        return 0;
    else
        return data[index] + SumVector(data, index + 1, size);
    endIf
endSubroutine

algorithm RunSumVector
    dimension vector[5] as integer;
    read vector[0];
    read vector[1];
    read vector[2];
    read vector[3];
    read vector[4];
    write SumVector(vector, 0, 5);
endAlgorithm
